insert into agencia.produtos (id, slug, nome, tipo, resumo, status, cor, bu_id, sobre, publico_alvo, proposta_de_valor, tagline, frase_de_impacto, contexto_mercado, posicionamento, dores, diferenciais, entregaveis, conteudo, objecoes, links, materiais, inicio, fim, local, modalidade, vagas, inicio_das_vendas, preco_referencia, politica_comercial, vendidas, atualizado_em) values
  ('imersao-cupola-aluguel', 'imersao-cupola-aluguel', 'Imersão CUPOLA Aluguel', 'Imersão · Treinamento', 'Uma nova maneira de gerir a locação imobiliária na era da Inteligência Artificial.', 'ativo', '#5FA8C4', 'educacao', 'Experiência de gestão para líderes de imobiliárias de locação que combina mapeamento da operação, preparação online com especialistas, benchmarking com referências e laboratórios práticos de aplicação da IA.', 'Gestores e líderes de imobiliárias de locação que buscam transformar processos, aplicar IA e preparar suas equipes para escala e eficiência operacional.', 'Preparação estratégica somada a imersão prática com especialistas, para gerar clareza, aprimorar processos e acelerar resultados com apoio da Inteligência Artificial.', 'Gerir locação na era da IA', 'A Imersão CUPOLA Aluguel é para o gestor que sabe que sua operação precisa evoluir, mas precisa mudar a mentalidade para alterar a forma como pensa e faz processos e a gestão de pessoas dentro das operações.', 'O mercado de locação está passando por uma transformação acelerada. A IA está redefinindo processos, relações com clientes e eficiência operacional.', 'Não é curso de ferramenta: é mudança de mentalidade sobre como se pensa processo e gestão de pessoas dentro de uma operação de locação.', '["Processos pouco eficientes e manuais","Baixa adoção de tecnologia e IA","Dificuldade para escalar operações","Falta de dados para tomada de decisão","Equipes pouco capacitadas","Experiência do cliente inconsistente"]'::jsonb, '["Benchmarking com imobiliárias referência","Especialistas e laboratórios de IA","Aplicação prática e resultados reais","Comunidade e networking qualificado"]'::jsonb, '["Mapeamento individual da operação","Preparação online com especialistas","Imersão presencial em Curitiba","Documento com caminhos e próximos passos"]'::jsonb, '["Mapeamento da operação — diagnóstico individual antes de começar","Preparação online com especialistas, assíncrona","Benchmarking com imobiliárias referência","Laboratórios práticos de aplicação de IA","Imersão presencial em Curitiba","Plano de próximos passos, por participante"]'::jsonb, '[{"id":"obj-caro","objecao":"Está caro.","resposta":"O investimento é abaixo do custo de uma contratação errada. O retorno vem na aplicação prática dos aprendizados e na melhoria dos resultados."},{"id":"obj-tempo","objecao":"Não tenho tempo para participar.","resposta":"A preparação online é assíncrona e a etapa presencial é intensa e objetiva, focada em resultados imediatos para a sua operação."},{"id":"obj-aplicar","objecao":"Não sei se minha equipe vai conseguir aplicar.","resposta":"Os laboratórios e o plano final são desenhados para a realidade da sua imobiliária, com próximos passos claros e aplicáveis."}]'::jsonb, '[{"id":"lk-lp","rotulo":"Landing page","url":"#"},{"id":"lk-inscricao","rotulo":"Página de inscrição","url":"#"},{"id":"lk-checkout","rotulo":"Checkout","url":"#"},{"id":"lk-apresentacao","rotulo":"Apresentação comercial","url":"#"}]'::jsonb, '[{"id":"mt-inst","nome":"Apresentação institucional","formato":"PPTX","url":"#"},{"id":"mt-reg","nome":"Regulamento","formato":"PDF","url":"#"},{"id":"mt-id","nome":"Identidade visual","formato":"ZIP","url":"#"},{"id":"mt-fotos","nome":"Fotos do evento","formato":"ZIP","url":"#"}]'::jsonb, '2026-10-27', '2026-11-17', 'Curitiba, PR', 'hibrido', 80, '2026-08-10', 9999, 'Lote promocional até o fim de agosto. Desconto para segundo participante da mesma imobiliária. Parcelamento em até 12 vezes.', 34, '2026-05-22')
